Script.Inputs = {
  image: "image"
};

function onChange() {
  function getImageDimensions(url, callback) {
  var img = new Image();

  // Set up an event listener to execute once the image has loaded
  img.onload = function() {
    // The image is now loaded; dimensions are available
    callback(this.width, this.height);
  };

  // Handle possible errors in loading the image (e.g., broken links)
  img.onerror = function() {
    console.log("There was an error loading the image.");
  };

  // Set the source of the image
  img.src = url;
  }

  getImageDimensions(Script.Inputs.image, (width, height) => {
    Script.Outputs.imageWidth = width;
    Script.Outputs.imageHeight = height;
  });


  Script.Outputs.imagePath = Script.Inputs.image;
  Script.Outputs.Done();
}

Script.Setters.image = onChange;

